# Load the metrics data if not already loaded
if 'metric_df' not in globals():
    metrics_path = telemetry.get_metrics()
    metric_df = pd.read_csv(metrics_path) if metrics_path else pd.DataFrame()

# Filter application metrics: these have columns rr, sr, cnt, mrt, tc
# Check if these columns exist to identify app metrics
app_metric_cols = {'timestamp', 'rr', 'sr', 'cnt', 'mrt', 'tc'}
if app_metric_cols.issubset(metric_df.columns):
    app_metrics_df = metric_df.copy()
else:
    app_metrics_df = pd.DataFrame()

# Convert timestamp to datetime with UTC+8 timezone
tz = pytz.timezone('Asia/Shanghai')
if not app_metrics_df.empty:
    app_metrics_df['datetime'] = pd.to_datetime(app_metrics_df['timestamp'], unit='s').dt.tz_localize('UTC').dt.tz_convert(tz)

# Calculate global thresholds using entire app metrics dataset before filtering
# For rr and sr, calculate P5 (5th percentile) to detect drops
# For cnt and mrt, calculate P95 (95th percentile) to detect spikes
global_thresholds_app = {}
if not app_metrics_df.empty:
    for kpi in ['rr', 'sr']:
        global_thresholds_app[kpi] = app_metrics_df[kpi].quantile(0.05)
    for kpi in ['cnt', 'mrt']:
        global_thresholds_app[kpi] = app_metrics_df[kpi].quantile(0.95)

# Define failure time window
start_time = pd.Timestamp('2021-03-06 06:00:00', tz=tz)
end_time = pd.Timestamp('2021-03-06 06:30:00', tz=tz)

# Filter app metrics data within failure time window
filtered_app_metrics_df = app_metrics_df[
    (app_metrics_df['datetime'] >= start_time) & (app_metrics_df['datetime'] <= end_time)
] if not app_metrics_df.empty else pd.DataFrame()

# Identify anomalies during failure window
# For rr and sr: anomaly if value < P5 threshold (drop)
# For cnt and mrt: anomaly if value > P95 threshold (spike)
def detect_anomalies(row):
    anomalies = {}
    for kpi in ['rr', 'sr']:
        if row[kpi] < global_thresholds_app[kpi]:
            anomalies[kpi] = 'below_threshold'
    for kpi in ['cnt', 'mrt']:
        if row[kpi] > global_thresholds_app[kpi]:
            anomalies[kpi] = 'above_threshold'
    return anomalies

if not filtered_app_metrics_df.empty:
    filtered_app_metrics_df['anomalies'] = filtered_app_metrics_df.apply(detect_anomalies, axis=1)
    # Filter rows with any anomalies
    anomalies_app_df = filtered_app_metrics_df[filtered_app_metrics_df['anomalies'].map(bool)].copy()
else:
    anomalies_app_df = pd.DataFrame()

# Summarize anomalies by component (tc) and KPI: count and timestamps
if not anomalies_app_df.empty:
    # Explode anomalies dict to rows
    anomalies_expanded = anomalies_app_df.explode('anomalies')
    # But anomalies is a dict, so convert to list of (kpi, status) tuples per row
    anomalies_expanded = anomalies_app_df[['tc', 'datetime', 'anomalies']].copy()
    anomalies_expanded = anomalies_expanded.explode('anomalies')
    # Actually, anomalies is a dict, so we convert to list of tuples first
    anomalies_expanded = anomalies_app_df[['tc', 'datetime', 'anomalies']].copy()
    anomalies_expanded = anomalies_expanded.assign(
        kpi_status=anomalies_expanded['anomalies'].apply(lambda d: list(d.items()) if isinstance(d, dict) else [])
    ).explode('kpi_status')
    anomalies_expanded = anomalies_expanded.drop(columns=['anomalies'])
    anomalies_expanded[['kpi', 'status']] = pd.DataFrame(anomalies_expanded['kpi_status'].tolist(), index=anomalies_expanded.index)
    anomalies_expanded = anomalies_expanded.drop(columns=['kpi_status'])

    # Group by component and KPI to get count and timestamps
    anomaly_summary_app = anomalies_expanded.groupby(['tc', 'kpi']).agg(
        anomaly_count=('status', 'size'),
        anomaly_timestamps=('datetime', lambda x: list(x))
    ).reset_index()
else:
    anomaly_summary_app = pd.DataFrame()

anomaly_summary_app
